<?php

declare(strict_types=1);

namespace NoResponse\LateResults;

use GuzzleHttp\Client;
use GuzzleHttp\ClientInterface;
use GuzzleHttp\Exception\GuzzleException;
use GuzzleHttp\Psr7\Request;
use NoResponse\Models\Errors\NotFoundException;
use NoResponse\Models\Shared\Account;
use NoResponse\Models\Shared\AccountRiskChangedEvent;
use NoResponse\Models\Shared\EnforcementAction;
use NoResponse\Models\Shared\EnforcementProvider;
use NoResponse\Models\Shared\EnforcementRequest;
use NoResponse\Models\Shared\EnforcementState;
use NoResponse\Models\Shared\EnforcementStatus;
use NoResponse\Models\Shared\Flow;
use NoResponse\NoResponseClient;
use NoResponse\WebhookVerification\Webhook;
use Psr\Http\Message\ResponseInterface;

/**
 * Late enforcement. Generated by tools/generate_overlays.py from tools/late_results/actions.json; do not edit.
 *
 * account.risk_changed only wakes the handler. handleRiskChange verifies the delivery, reads the account's current
 * risk (GET /v1/accounts/{account_id}), asks your getAccountState where the account is in your own flow, and takes
 * the actions the table names for that state and the decision of its flow:
 *
 *   onboarding   account_creation review/block  fail_onboarding, revoke_sessions
 *   provisional  account_creation review/block  reject_activation, revoke_sessions
 *   active       login review                   revoke_sessions
 *   active       login block                    restrict, revoke_sessions
 *   restricted   login allow                    unrestrict, when $flows['login']['reinstate']
 *
 * Every action, or none, is recorded with accounts->recordEnforcement at the riskVersion read, and a refused action
 * is recorded as failed and thrown. No action deletes a user. The same table and vectors
 * (tests/fixtures/late-results-vectors.json) run in every SDK.
 */
final class LateResults
{
    private const TABLE = '{"lifecycle":{"onboarding":{"flow":"account_creation","on":{"review":["fail_onboarding","revoke_sessions"],"block":["fail_onboarding","revoke_sessions"]}},"provisional":{"flow":"account_creation","on":{"review":["reject_activation","revoke_sessions"],"block":["reject_activation","revoke_sessions"]}},"active":{"flow":"login","on":{"review":["revoke_sessions"],"block":["restrict","revoke_sessions"]}},"restricted":{"flow":"login","on":{},"reinstate":{"allow":["unrestrict"]}},"rejected":{"flow":"account_creation","on":{}}},"providers":{"clerk":{"base_url":"https://api.clerk.com/v1","actions":{"fail_onboarding":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"reject_activation":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"restrict":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"unrestrict":[{"call":{"method":"POST","path":"/users/{user}/unban"}}],"revoke_sessions":[{"each":{"list":{"method":"GET","path":"/sessions","query":{"user_id":"{user}","status":"active","limit":"100"}},"page":{"kind":"offset","param":"offset","size":100},"where":{"status":"active"}},"call":{"method":"POST","path":"/sessions/{item}/revoke"}}]}},"workos":{"base_url":"https://api.workos.com","actions":{"fail_onboarding":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"onboarding_failed"}}}}],"reject_activation":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"activation_rejected"}}}}],"restrict":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"restricted"}}}}],"unrestrict":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":null}}}}],"revoke_sessions":[{"each":{"list":{"method":"GET","path":"/user_management/users/{user}/sessions","query":{"limit":"100"}},"page":{"kind":"cursor","param":"after","next":["list_metadata","after"]},"where":{"status":"active"}},"call":{"method":"POST","path":"/user_management/sessions/revoke","body":{"session_id":"{item}"}}}]}},"auth0":{"base_url":"https://{domain}/api/v2","actions":{"fail_onboarding":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"reject_activation":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"restrict":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"unrestrict":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":false}}}],"revoke_sessions":[{"call":{"method":"DELETE","path":"/users/{user}/sessions"},"fallback":{"status":403,"code":"feature_not_enabled","reports":"restrict","steps":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}]}},{"call":{"method":"DELETE","path":"/users/{user}/refresh-tokens"},"fallback":{"status":403,"code":"feature_not_enabled","steps":[{"each":{"list":{"method":"GET","path":"/device-credentials","query":{"user_id":"{user}","type":"refresh_token","per_page":"100"}},"page":{"kind":"index","param":"page","size":100}},"call":{"method":"DELETE","path":"/device-credentials/{item}"}},{"each":{"list":{"method":"GET","path":"/device-credentials","query":{"user_id":"{user}","type":"rotating_refresh_token","per_page":"100"}},"page":{"kind":"index","param":"page","size":100}},"call":{"method":"DELETE","path":"/device-credentials/{item}"}}]}}]}}},"limits":{"retries":4,"budget_ms":3000,"backoff_ms":250,"max_pages":100}}';

    private const FLOW_PROPERTIES = ['account_creation' => 'accountCreation', 'login' => 'login', 'purchase' => 'purchase'];

    /** @var array<string, mixed>|null */
    private static ?array $table = null;

    /** @return array<string, mixed> */
    private static function table(): array
    {
        return self::$table ??= json_decode(self::TABLE, true, 512, JSON_THROW_ON_ERROR);
    }

    /**
     * Verify an account.risk_changed delivery and enforce the account's current risk. A delivery that fails
     * verification throws WebhookVerificationException before anything is read; any other event, and a test event,
     * does nothing.
     *
     * @param  array<string, string|array<string>>  $headers
     * @param  array<string, string>  $secrets
     * @param  callable(Account): ?AccountStateAnswer  $getAccountState  The account's state in your flow; null for an account you do not hold.
     * @param  array<string, array{reinstate?: bool}>  $flows  Per flow: reinstate lifts a restriction once the decision is allow again (off by default).
     */
    public static function handleRiskChange(
        NoResponseClient $client,
        string $payload,
        array $headers,
        array $secrets,
        ActionProvider $provider,
        callable $getAccountState,
        array $flows = [],
        int $toleranceSeconds = Webhook::DEFAULT_TOLERANCE_SECONDS,
        ?int $now = null,
    ): EnforcementResult {
        $event = Webhook::constructEvent($payload, $headers, $secrets, $toleranceSeconds, $now);
        if (! $event instanceof AccountRiskChangedEvent || $event->test === true) {
            return new EnforcementResult(event: $event, skipped: 'not_actionable');
        }
        try {
            $account = $client->accounts->get($event->data->account->id)->result;
        } catch (NotFoundException) {
            return new EnforcementResult(event: $event, skipped: 'account_gone');
        }
        $result = self::enforceAccount($client, $account, $provider, $getAccountState, $flows);

        return new EnforcementResult($event, $result->account, $result->state, $result->riskVersion, $result->skipped, $result->enforcements);
    }

    /**
     * Enforce one account as read: the account a handler fetched, or one from
     * accounts->listChanged(unenforced: true) when catching up.
     *
     * @param  callable(Account): ?AccountStateAnswer  $getAccountState
     * @param  array<string, array{reinstate?: bool}>  $flows
     */
    public static function enforceAccount(
        NoResponseClient $client,
        Account $account,
        ActionProvider $provider,
        callable $getAccountState,
        array $flows = [],
    ): EnforcementResult {
        $answer = $getAccountState($account);
        if ($answer === null) {
            return new EnforcementResult(account: $account, skipped: 'unknown_user');
        }
        $state = $answer->state;
        $rule = self::table()['lifecycle'][$state] ?? null;
        if ($rule === null) {
            throw new \InvalidArgumentException("unknown account state {$state}");
        }
        $riskVersion = $account->riskVersion;
        if ($answer->enforcedRiskVersion !== null && $riskVersion <= $answer->enforcedRiskVersion) {
            return new EnforcementResult(account: $account, state: $state, riskVersion: $riskVersion, skipped: 'already_enforced');
        }
        $flow = $rule['flow'];
        // An open enum: a decision this SDK does not know arrives as its raw string.
        $decision = $account->decisionsByFlow->{self::FLOW_PROPERTIES[$flow]};
        $decision = $decision instanceof \BackedEnum ? $decision->value : $decision;
        $actions = $rule['on'][$decision] ?? null;
        if ($actions === null && ($flows[$flow]['reinstate'] ?? false)) {
            $actions = $rule['reinstate'][$decision] ?? null;
        }
        $enforcements = [];
        $record = function (string $action, string $status, ?string $errorCode = null) use ($client, $account, $riskVersion, $flow, $state, $provider, &$enforcements): void {
            $client->accounts->recordEnforcement(new EnforcementRequest(
                riskVersion: $riskVersion,
                flow: Flow::from($flow),
                action: EnforcementAction::from($action),
                stateBefore: EnforcementState::from($state),
                status: EnforcementStatus::from($status),
                provider: EnforcementProvider::from($provider->name()),
                errorCode: $errorCode,
            ), $account->id);
            $enforcements[] = new Enforced($flow, $action, $status, $errorCode);
        };
        if (! $actions) {
            // An adverse or step_up decision that needs nothing still counts as handled.
            if ($decision !== 'allow') {
                $record('none', 'applied');
            }

            return new EnforcementResult(account: $account, state: $state, riskVersion: $riskVersion, enforcements: $enforcements);
        }
        $recorded = [];
        foreach ($actions as $action) {
            try {
                $alsoRan = $provider->run($action, $answer->userId ?: $account->id);
            } catch (\Throwable $error) {
                $record($action, 'failed', self::failureCode($provider->name(), $error));
                throw $error;
            }
            foreach ([...$alsoRan, $action] as $ran) {
                if (! isset($recorded[$ran])) {
                    $recorded[$ran] = true;
                    $record($ran, 'applied');
                }
            }
        }

        return new EnforcementResult(account: $account, state: $state, riskVersion: $riskVersion, enforcements: $enforcements);
    }

    /** The error_code of a failed action: the provider's code, else its HTTP status, as <provider>.<code>. */
    private static function failureCode(string $provider, \Throwable $error): string
    {
        $suffix = 'error';
        if ($error instanceof ProviderActionException) {
            $code = $error->errorCode === null ? null : strtolower($error->errorCode);
            $suffix = match (true) {
                $code !== null && preg_match('/\A[a-z0-9_.-]+\z/', $code) === 1 => $code,
                $error->status === 0 => 'unreachable',
                default => "http_{$error->status}",
            };
        }

        return substr("{$provider}.{$suffix}", 0, 128);
    }

    /**
     * Clerk, WorkOS or Auth0, run from the shared action table. $token is the Clerk secret key, WorkOS API key or
     * Auth0 Management API token; $domain is the Auth0 tenant domain. Pass $http for a proxy or for tests.
     */
    public static function identityProvider(
        string $name,
        string $token,
        ?string $domain = null,
        ?string $baseUrl = null,
        ?ClientInterface $http = null,
    ): ActionProvider {
        $spec = self::table()['providers'][$name] ?? null;
        if ($spec === null) {
            throw new \InvalidArgumentException("unknown identity provider {$name}");
        }
        if ($token === '') {
            throw new \InvalidArgumentException("{$name} needs token");
        }
        $base = $baseUrl ?? $spec['base_url'];
        if (str_contains($base, '{domain}')) {
            if ($domain === null || $domain === '') {
                throw new \InvalidArgumentException("{$name} needs domain or baseUrl");
            }
            $base = str_replace('{domain}', $domain, $base);
        }
        $context = ['name' => $name, 'base' => rtrim($base, '/'), 'authorization' => "Bearer {$token}", 'http' => $http ?? new Client(['timeout' => 10])];

        return new class($spec['actions'], $context) implements ActionProvider
        {
            /**
             * @param  array<string, list<array<string, mixed>>>  $actions
             * @param  array{name: string, base: string, authorization: string, http: ClientInterface}  $context
             */
            public function __construct(private readonly array $actions, private readonly array $context)
            {
            }

            public function name(): string
            {
                return $this->context['name'];
            }

            public function run(string $action, string $userId): array
            {
                if ($userId === '') {
                    throw new \InvalidArgumentException('user id must be a non-empty string');
                }
                $steps = $this->actions[$action] ?? throw new \InvalidArgumentException("unknown action {$action}");
                $context = $this->context + ['user' => $userId, 'waited_ms' => 0.0];

                return LateResults::runSteps($steps, $context);
            }
        };
    }

    /**
     * Your own user store: one callable per action you support, keyed by action, taking the user id and returning
     * null or any other action it took. An action without one fails.
     *
     * @param  array<string, callable(string): (list<string>|null|void)>  $handlers
     */
    public static function customProvider(array $handlers): ActionProvider
    {
        return new class($handlers) implements ActionProvider
        {
            /** @param  array<string, callable>  $handlers */
            public function __construct(private readonly array $handlers)
            {
            }

            public function name(): string
            {
                return 'custom';
            }

            public function run(string $action, string $userId): array
            {
                $handler = $this->handlers[$action] ?? throw new \InvalidArgumentException("customProvider has no {$action} handler");

                $alsoRan = ($handler)($userId);

                // Only a list of action names counts; any other return value (null, true, a model) is no extra action.
                return is_array($alsoRan) ? array_values(array_filter(
                    $alsoRan,
                    fn ($name) => is_string($name) && $name !== 'none' && EnforcementAction::tryFrom($name) !== null,
                )) : [];
            }
        };
    }

    /**
     * @internal  The table interpreter, called by identityProvider's provider.
     *
     * @param  list<array<string, mixed>>  $steps
     * @param  array<string, mixed>  $context
     * @return list<string>
     */
    public static function runSteps(array $steps, array &$context): array
    {
        $alsoRan = [];
        foreach ($steps as $step) {
            if (isset($step['each'])) {
                foreach (self::collect($step['each'], $context) as $item) {
                    self::send($step['call'], $context, $item);
                }

                continue;
            }
            try {
                self::send($step['call'], $context);
            } catch (ProviderActionException $error) {
                $fallback = $step['fallback'] ?? null;
                if ($fallback === null || $error->status !== $fallback['status'] || $error->errorCode !== $fallback['code']) {
                    throw $error;
                }
                array_push($alsoRan, ...self::runSteps($fallback['steps'], $context));
                if (isset($fallback['reports'])) {
                    $alsoRan[] = $fallback['reports'];
                }
            }
        }

        return $alsoRan;
    }

    /**
     * Every matching item id across the list's pages, collected before any is acted on.
     *
     * @param  array<string, mixed>  $each
     * @param  array<string, mixed>  $context
     * @return list<string>
     */
    private static function collect(array $each, array &$context): array
    {
        ['list' => $list, 'page' => $page] = $each;
        $where = $each['where'] ?? [];
        $ids = [];
        $cursor = null;
        for ($index = 0; $index < self::table()['limits']['max_pages']; $index++) {
            $query = $list['query'] ?? [];
            if ($page['kind'] === 'offset') {
                $query[$page['param']] = (string) ($index * $page['size']);
            } elseif ($page['kind'] === 'index') {
                $query[$page['param']] = (string) $index;
            } elseif ($cursor !== null) {
                $query[$page['param']] = $cursor;
            }
            $body = self::send(['query' => $query] + $list, $context);
            $items = is_array($body) && array_is_list($body) ? $body : (is_array($body['data'] ?? null) ? $body['data'] : []);
            foreach ($items as $item) {
                $id = is_array($item) ? ($item['id'] ?? null) : null;
                if (! is_string($id) || $id === '') {
                    continue;
                }
                $matches = true;
                foreach ($where as $key => $value) {
                    $matches = $matches && array_key_exists($key, $item) && $item[$key] === $value;
                }
                if ($matches) {
                    $ids[] = $id;
                }
            }
            if ($page['kind'] === 'cursor') {
                $next = $body;
                foreach ($page['next'] as $key) {
                    $next = is_array($next) ? ($next[$key] ?? null) : null;
                }
                if (! is_string($next) || $next === '') {
                    break;
                }
                $cursor = $next;
            } elseif (count($items) < $page['size']) {
                break;
            }
        }

        return $ids;
    }

    private static function fill(mixed $value, string $user, ?string $item): mixed
    {
        if (is_string($value)) {
            return str_replace(['{user}', '{item}'], [$user, $item ?? ''], $value);
        }
        if (is_array($value)) {
            return array_map(fn (mixed $entry): mixed => self::fill($entry, $user, $item), $value);
        }

        return $value;
    }

    /** How long a 429 asks to wait, in milliseconds. */
    private static function rateLimitWaitMs(ResponseInterface $response, int $retry): float
    {
        $after = trim($response->getHeaderLine('Retry-After'));
        if (is_numeric($after) && (float) $after >= 0) {
            return (float) $after * 1000;
        }
        $reset = trim($response->getHeaderLine('X-RateLimit-Reset'));
        if (is_numeric($reset)) {
            return max(0.0, (float) $reset * 1000 - microtime(true) * 1000);
        }

        return (float) (self::table()['limits']['backoff_ms'] * 2 ** $retry);
    }

    /** The provider's error code: Auth0's errorCode, WorkOS's code or Clerk's errors[0].code. */
    private static function errorCode(string $text): ?string
    {
        $body = json_decode($text, true);
        if (! is_array($body)) {
            return null;
        }
        $code = $body['errorCode'] ?? $body['code'] ?? $body['errors'][0]['code'] ?? null;

        return is_string($code) && $code !== '' ? $code : null;
    }

    /**
     * One admin API call. A 404 is done (null); a 429 is waited out inside the action's budget; any other failure
     * throws ProviderActionException.
     *
     * @param  array<string, mixed>  $request
     * @param  array<string, mixed>  $context
     */
    private static function send(array $request, array &$context, ?string $item = null): mixed
    {
        $limits = self::table()['limits'];
        $user = $context['user'];
        $path = str_replace(['{user}', '{item}'], [rawurlencode($user), rawurlencode($item ?? '')], $request['path']);
        $url = $context['base'].$path;
        $query = self::fill($request['query'] ?? [], $user, $item);
        if ($query) {
            $url .= '?'.http_build_query($query, '', '&', PHP_QUERY_RFC3986);
        }
        $headers = ['Authorization' => $context['authorization'], 'Accept' => 'application/json'];
        $body = null;
        if (array_key_exists('body', $request)) {
            $body = json_encode(self::fill($request['body'], $user, $item), JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES);
            $headers['Content-Type'] = 'application/json';
        }
        $label = "{$context['name']} {$request['method']} {$request['path']}";
        for ($retry = 0; ; $retry++) {
            try {
                $response = $context['http']->send(new Request($request['method'], $url, $headers, $body), ['http_errors' => false]);
            } catch (GuzzleException $error) {
                throw new ProviderActionException($context['name'], 0, "{$label} failed: {$error->getMessage()}", null, $error);
            }
            $status = $response->getStatusCode();
            if ($status === 429 && $retry < $limits['retries']) {
                $wait = self::rateLimitWaitMs($response, $retry);
                if ($limits['budget_ms'] >= $context['waited_ms'] + $wait) {
                    $context['waited_ms'] += $wait;
                    usleep((int) ($wait * 1000));

                    continue;
                }
            }
            $text = (string) $response->getBody();
            if ($status === 404) {
                return null;
            }
            if ($status < 200 || $status >= 300) {
                throw new ProviderActionException($context['name'], $status, "{$label} answered {$status}", self::errorCode($text));
            }

            return $text === '' ? null : json_decode($text, true);
        }
    }
}
